diff --git a/lib/utils/parse/ast.go b/lib/utils/parse/ast.go
new file mode 100644
index 0000000000000..f13f7cd99b733
--- /dev/null
+++ b/lib/utils/parse/ast.go
@@ -0,0 +1,487 @@
+/*
