+
+func regexpMatch(match string) Expr {
+	return &RegexpMatchExpr{re: regexp.MustCompile(match)}
+}
+
+func regexpNotMatch(match string) Expr {
+	return &RegexpNotMatchExpr{re: regexp.MustCompile(match)}
